const {launch}=require('./launch.cjs');
const assert=require('node:assert/strict');
const fs=require('node:fs/promises');
const path=require('node:path');
(async()=>{
 const browser=await launch({headless:true,args:['--no-sandbox']});
 try{
  const context=await browser.newContext({viewport:{width:1600,height:1000}}),page=await context.newPage(),errors=[];
  context.on('page',p=>p.on('pageerror',e=>{errors.push(e.message);console.error(e.message);}));page.on('pageerror',e=>{errors.push(e.message);console.error(e.message);});page.setDefaultTimeout(10000);
  await context.addInitScript(()=>{window.sent=[];const send=WebSocket.prototype.send;WebSocket.prototype.send=function(d){sent.push(JSON.parse(d));return send.call(this,d);};});
  const ready=p=>p.waitForFunction(()=>typeof replaying!=='undefined'&&!replaying&&socket?.readyState===1);
  const contains=(p,text)=>p.waitForFunction(text=>Array.from({length:terminal.buffer.active.length},(_,i)=>terminal.buffer.active.getLine(i)?.translateToString(true)).join('\n').includes(text),text);
  const text=p=>p.evaluate(()=>Array.from({length:terminal.buffer.active.length},(_,i)=>terminal.buffer.active.getLine(i)?.translateToString(true)).join('\n'));
  const control=async(p,q)=>{const u=new URL(p,process.argv[3]);for(const[k,v]of Object.entries(q))u.searchParams.set(k,v);const r=await fetch(u,{method:'POST'});if(!r.ok)throw Error(await r.text());return r.json();};
  await page.goto(process.argv[2]);await ready(page);await contains(page,'SSH transport healthy');
  for(const id of ['search-toggle','appearance-open','search-close','appearance-close','history-close']){assert.equal(await page.locator('#'+id+' svg').count(),1);assert.equal((await page.locator('#'+id).textContent()).trim(),'');assert(await page.locator('#'+id).getAttribute('aria-label'));}
  assert.equal(await page.locator('#filter-toggle').count(),0);assert.equal(await page.locator('#source-gutter').getAttribute('aria-expanded'),'false');assert((await page.locator('#source-gutter').boundingBox()).width<=10);
  await page.locator('#source-gutter').click();await page.waitForFunction(()=>preferences.gutterExpanded);await page.waitForSelector('.source-time');assert.match(await page.locator('.source-time').first().textContent(),/\d\d:\d\d:\d\d\.\d{3}/);
  assert(await page.evaluate(()=>transcript.rows.filter(r=>r.kind==='output').every(r=>!!r.time)));
  const rowData=await page.evaluate(()=>{const canvas=document.querySelector('.source-canvas'),ctx=canvas.getContext('2d'),dpr=window.devicePixelRatio||1;const rows=[...document.querySelectorAll('.source-row')];return rows.map(el=>({kind:el.dataset.kind,stream:el.dataset.stream,color:Array.from(ctx.getImageData(Math.floor(3*dpr),Math.floor((parseFloat(el.style.top)+parseFloat(el.style.height)/2)*dpr),1,1).data)}));});
  const out=rowData.find(r=>r.stream==='stdout'&&r.kind==='output'),err=rowData.find(r=>r.stream==='stderr'&&r.kind==='output');assert(out&&err);assert.deepEqual(out.color,err.color);assert.equal(out.color[3],255);
  await page.keyboard.press('Control+f');await page.locator('#search-text').fill('WARNING');await page.waitForFunction(()=>terminalQuery?.results.length===1);await page.locator('.search-result').first().click();assert((await page.evaluate(()=>terminal.getSelection())).includes('WARNING'));
  await control('/create',{name:'hostname'});await contains(page,'demo-server');
  await page.locator('#search-only').check();await page.locator('#search-before').fill('1');await page.locator('#search-before').dispatchEvent('change');await page.waitForFunction(()=>preferences.search.before===1&&!terminalQuery.busy&&terminalQuery.visibleRows.length>=2&&terminalQuery.visibleRows.every(r=>r.kind==='gap'||r.handle==='task1'));assert(!(await text(page)).includes('demo-server'));assert((await text(page)).includes('WARNING'));
  const screenshots=process.env.KEEPSESS_SCREENSHOT_DIR;if(screenshots){await fs.mkdir(screenshots,{recursive:true});await page.screenshot({path:path.join(screenshots,'search-context.png')});}
  await page.locator('#search-only').uncheck();await contains(page,'demo-server');
  console.log('search: provenance and first result passed');
  const a=await control('/create',{name:'short-search-a'}),b=await control('/create',{name:'short-search-b'});await contains(page,'short-search-b initial line 001');
  assert.equal(await page.locator('#search-task-scope').getAttribute('open'),null);assert.equal(await page.locator('#filter-sources').isVisible(),false);await page.locator('#search-task-scope summary').click();
  await page.locator('#search-text').fill('initial');await page.locator('#filter-sources').selectOption([a.handle]);await page.waitForFunction(id=>terminalQuery.results.length===2&&terminalQuery.results.every(r=>r.row.handle===id),a.handle);
  await page.locator('#task-scope-clear').click();await page.waitForFunction(()=>preferences.filter.sources.length===0&&terminalQuery.results.length===4);assert.equal(await page.locator('#search-text').inputValue(),'initial');assert(await page.locator('#task-scope-clear').isDisabled());assert.match(await page.locator('#task-scope-status').textContent(),/全部任务/);await page.locator('#filter-sources').selectOption([a.handle]);await page.waitForFunction(()=>terminalQuery.results.length===2);
  await page.locator('#search-only').check();await page.waitForFunction(()=>terminalQuery.visibleRows.every(r=>r.kind==='gap'||r.handle===preferences.filter.sources[0]));assert(!(await text(page)).includes('short-search-b'));
  await control('/bytes',{name:'short-search-a',hex:Buffer.from('中😀\tWIDE-needle '+ 'x'.repeat(150)+'\n').toString('hex')});await page.locator('#search-text').fill('wide-needle');await page.waitForFunction(()=>terminalQuery.results.length===1&&terminalQuery.results[0].plain.includes('WIDE-needle'));await page.locator('.search-result').click();assert.equal(await page.evaluate(()=>terminal.getSelection()),'WIDE-needle');
  const firstTime=await page.evaluate(()=>terminalQuery.results[0].row.time);await page.locator('#appearance-open').click();await page.locator('#font-size').fill('18');await page.locator('#font-size').dispatchEvent('input');await page.locator('#appearance-close').click();await page.waitForFunction(()=>!terminalQuery.busy&&terminal.options.fontSize===18);await page.locator('.search-result').click();assert.equal(await page.evaluate(()=>terminal.getSelection()),'WIDE-needle');assert.equal(await page.evaluate(()=>terminalQuery.results[0].row.time),firstTime);
  await page.locator('#search-advanced summary').click();await page.locator('#filter-reset').click();await page.locator('#search-text').fill('split-needle');await control('/bytes',{name:'short-search-a',hex:Buffer.from('split-nee').toString('hex')});await control('/bytes',{name:'short-search-a',hex:Buffer.from('dle found\n').toString('hex')});await page.waitForFunction(()=>terminalQuery.results.some(r=>r.plain.includes('split-needle found')));
  await page.locator('#search-clear').click();await contains(page,'short-search-b initial line 001');
  await page.evaluate(()=>{const row=transcript.rows.find(r=>r.plain.includes('WARNING'));terminal.scrollToLine(row.marker.line);terminal.select(0,row.marker.line,7);});await page.locator('#terminal .xterm-screen').click({button:'right',position:{x:280,y:8}});await page.getByRole('menuitem',{name:'查找所选内容',exact:true}).click();await page.waitForFunction(()=>preferences.search.query.length>0);assert(await page.locator('#search-panel').isVisible());assert.equal(await page.evaluate(()=>sent.filter(x=>x.type==='input').length),0);
  await page.locator('#search-clear').click();await page.locator('#search-close').click();
  if(screenshots)await page.screenshot({path:path.join(screenshots,'source-expanded.png')});
  await page.locator('#source-gutter').click();if(screenshots)await page.screenshot({path:path.join(screenshots,'source-collapsed.png')});
  console.log('search: tasks, projection and menus passed');
  const popup=context.waitForEvent('page');await page.locator('#open-terminal').click();const human=await popup;human.setDefaultTimeout(10000);await ready(human);await human.locator('#mode').click();await human.waitForFunction(()=>unlocked);await human.locator('#shell-start').click();await human.waitForFunction(()=>handle&&!replaying&&socket?.readyState===1);await human.locator('#mode').click();await human.waitForFunction(()=>unlocked);await human.locator('.xterm-helper-textarea').focus();await human.keyboard.type('echo terminal-alive');await human.keyboard.press('Enter');await contains(human,'terminal-alive');await human.waitForFunction(()=>!operationPending&&!inputQueue);
  const inputCount=await human.evaluate(()=>sent.filter(x=>x.type==='input').length);await human.locator('.xterm-helper-textarea').focus();await human.keyboard.press('Control+f');await human.locator('#search-text').fill('terminal-alive');await human.evaluate(()=>updateControls());assert.equal(await human.locator('#search-text').inputValue(),'terminal-alive');await human.waitForFunction(()=>terminalQuery.results.length>=2).catch(async e=>{console.log(await human.evaluate(()=>({prefs:preferences.search,status:document.getElementById('search-status').textContent,results:terminalQuery.results.map(r=>r.plain),rows:Array.from({length:terminal.buffer.active.length},(_,i)=>terminal.buffer.active.getLine(i)?.translateToString(true))})));throw e;});await human.locator('.search-result').last().click();assert((await human.evaluate(()=>terminal.getSelection())).includes('terminal-alive'));assert.equal(await human.evaluate(()=>sent.filter(x=>x.type==='input').length),inputCount);assert(await human.locator('#search-only').isDisabled());
  if(screenshots)await human.screenshot({path:path.join(screenshots,'human-search.png')});
  await human.evaluate(()=>new Promise(r=>terminal.write('\x1b[?1049hALT needle 中',r)));await human.locator('#search-text').fill('ALT needle');await human.waitForFunction(()=>terminal.buffer.active.type==='alternate'&&terminalQuery.results.length===1);await human.locator('.search-result').click();assert((await human.evaluate(()=>terminal.getSelection())).includes('ALT needle'));
  await human.evaluate(async()=>{await new Promise(r=>terminal.write('\x1b[?1049l',r));await terminalQuery.jump(0);});await human.waitForFunction(()=>terminal.buffer.active.type==='normal'&&terminalQuery.results.length===0);assert.equal(await human.evaluate(()=>sent.filter(x=>x.type==='input').length),inputCount);

  await page.bringToFront();await page.keyboard.press('Control+f');await page.locator('#search-text').fill('initial');await page.waitForFunction(()=>terminalQuery.results.length>=4);await page.locator('#search-close').click();await page.reload();await ready(page);assert.equal(await page.locator('#search-panel').isVisible(),false);assert.equal(await page.locator('#search-text').inputValue(),'initial');
  await page.waitForFunction(()=>terminalQuery.results.length>=4);await page.evaluate(()=>{generation++;socket?.close();terminal.dispose();terminal=null;selected='';});assert.equal(await page.locator('#search-results-space').evaluate(el=>el.childElementCount),0);assert.match(await page.locator('#search-status').textContent(),/选择一个终端/);
  assert.deepEqual(errors,[]);console.log('unified search passed: results, jumps, task context, packet splits, timestamps, strips, right-click, human terminal, no input replay');
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exitCode=1;});
